'use client';
import { FormEvent,useEffect,useState } from 'react';
import Link from 'next/link';
import { api } from '@/lib/api';
type Appeal={id:string;body:string;status:string;resolutionNote:string|null;createdAt:string};type Action={id:string;targetType:string;actionType:string;reason:string;createdAt:string;reversedAt:string|null;appeals:Appeal[];actor:{username:string;displayName:string}|null};const targetNames:Record<string,string>={PUBLICATION:'Публикация',COMMENT:'Комментарий',USER:'Аккаунт'};const actionNames:Record<string,string>={HIDE:'Скрытие',WARNING:'Предупреждение',RESTRICT:'Ограничение',BAN:'Блокировка'};const appealNames:Record<string,string>={PENDING:'На рассмотрении',ACCEPTED:'Принята',REJECTED:'Отклонена'};
export default function ModerationHistory(){const[items,setItems]=useState<Action[]>([]);const[error,setError]=useState('');const[message,setMessage]=useState('');const load=()=>api<Action[]>('/moderation/actions').then(setItems).catch(e=>setError(e.message));useEffect(()=>{void load();},[]);async function appeal(e:FormEvent<HTMLFormElement>,id:string){e.preventDefault();try{const f=new FormData(e.currentTarget);await api(`/moderation/actions/${id}/appeal`,{method:'POST',body:JSON.stringify({body:f.get('body')})});setMessage('Апелляция отправлена');await load();}catch(c){setError(c instanceof Error?c.message:'Ошибка');}}return <div className="settings-narrow"><div className="section-title"><div><h1>Решения модерации</h1><p className="muted">Здесь видны причины и результат апелляций. Публичной доски наказаний нет.</p></div><Link className="button ghost" href="/settings">Назад</Link></div>{message&&<div className="success-box">{message}</div>}{error&&<div className="error-box">{error}</div>}<div className="publication-list">{items.map(a=><article className="card" key={a.id}><div className="publication-topline"><span className="type-label">{targetNames[a.targetType]??a.targetType}</span><span className="type-label">{a.reversedAt?'Отменено':'Действует'}</span></div><h2>{actionNames[a.actionType]??a.actionType}</h2><p>{a.reason}</p><p className="muted small-text">{new Date(a.createdAt).toLocaleString('ru-RU')} · модератор {a.actor?`@${a.actor.username}`:'система'}</p>{a.appeals[0]?<div className={a.appeals[0].status==='ACCEPTED'?'success-box':a.appeals[0].status==='REJECTED'?'error-box':'notice'}><strong>Апелляция: {appealNames[a.appeals[0].status]??a.appeals[0].status}</strong><p>{a.appeals[0].body}</p>{a.appeals[0].resolutionNote&&<p>{a.appeals[0].resolutionNote}</p>}</div>:!a.reversedAt&&<form onSubmit={e=>appeal(e,a.id)}><label>Почему решение нужно пересмотреть<textarea name="body" minLength={20} maxLength={2000} required/></label><button className="button secondary">Отправить апелляцию</button></form>}</article>)}{!items.length&&<div className="empty-state">В отношении аккаунта нет решений модерации.</div>}</div></div>}
